INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('chenqiao-mutiny','陈桥兵变','politics','point','year',NULL,NULL,'显德七年正月初三至初四（960），《续资治通鉴长编》等记载陈桥拥立及次日入京。',960,12,NULL,11531,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'后周显德七年，朝廷命殿前都点检赵匡胤率军北上应对北汉、契丹来报。军队行至陈桥驿后拥立赵匡胤，赵随即率军返回开封，后周恭帝柴宗训禅位，赵匡胤建立宋朝。兵变以军队拥立完成政权更替，也开启北宋统一进程。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('dong-zhuo-enters-luoyang','董卓进京','politics','point','month',NULL,NULL,'中平六年八月末；按《后汉书·孝灵帝纪》所载少帝等于八月辛未还宫及董卓迎回少帝的记事，取公历189年9月25日为董卓护送少帝返回洛阳的年内节点；9月28日为其废立皇帝之日，不取作进京时间。',189,9,NULL,2276,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'董卓率军进入洛阳并控制朝廷，随后废黜汉少帝刘辩、拥立刘协为帝，东汉皇权由此进一步受制于军阀。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('ganlu-coup','甘露之变','politics','point','year',NULL,NULL,'大和九年十一月二十一日（农历），甘露之变发生；该日期对应公历835年。',835,12,NULL,10031,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'唐文宗与李训、郑注谋划削弱宦官势力，借左金吾仗院出现甘露的消息诱宦官前往察看，伏兵却未能制胜。仇士良等宦官挟持文宗并调禁军反击，李训等人出逃后被杀，王涯、贾餗、舒元舆等朝臣遭株连；宦官此后进一步控制朝政。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('he-jin-killed','何进被杀','politics','point','month',NULL,NULL,'《后汉书·孝灵帝纪》记为中平六年八月戊辰；据该年历日换算为公历189年9月22日。',189,9,NULL,2276,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'大将军何进谋划诛除宦官，计划泄露后被宦官诱杀于宫中。袁绍等率军攻入宫禁，戚宦冲突演变为朝廷武装混战，为董卓控制洛阳创造了局势。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('heirloom-seal-lost','传国玉玺失踪','politics','point','approximate_year',NULL,NULL,'传国玺失踪的具体时点及是否毁于火中，记载存在差异，事件约在后唐灭亡前后。',936,12,NULL,11243,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'后唐末帝李从珂兵败自焚，传统记载称传国玉玺随之失去下落；此后宋太祖受禅时已不见传国玺。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('jin-reclaims-yanyun','金重新夺取燕云','battle','point','year',NULL,NULL,'1125—1126年金军重夺燕云并南下；以1125年为事件起点，靖康之变另有独立事件。',1125,12,NULL,13511,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'宋金矛盾激化后，金军重新控制燕云并南下攻宋，北宋北部防线崩溃，次年开封陷落。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('jin-west-court-forced-to-changan','西晋朝廷被挟至长安','politics','point','year',NULL,NULL,'《晋书·惠帝纪》记永安元年冬十一月乙未张方劫晋惠帝至长安；该月为农历，公历日期未能可靠确定。',304,12,NULL,3659,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'八王之乱中，河间王司马颙的部将张方为控制朝廷，于永安元年（304）挟持晋惠帝司马衷及公卿由洛阳西往长安，司马颙以征西府为帝宫。洛阳仍留有官员组成的留台承制行事；惠帝至306年六月才被迎回洛阳，期间长安成为朝廷实际所在。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('kublai-court-at-kaiping','忽必烈以开平为汗廷','politics','point','year',NULL,NULL,'中统元年（1260年）；此时汗位之争未结束，不将开平写成蒙古帝国唯一都城。',1260,12,NULL,15131,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'忽必烈在开平即大汗位，与仍据和林的阿里不哥争位；开平成为忽必烈一方的政治中心，蒙古帝国一度出现两个汗廷。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('kublai-moves-capital-to-zhongdu','忽必烈迁都中都','politics','point','year',NULL,NULL,'至元四年（1267年）；北京地方志资料记为迁都中都之年。',1267,12,NULL,15215,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'忽必烈由上都迁往中都（今北京），上都转为陪都，并在中都东北营建新城。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('later-jin-cedes-yanyun','后晋割让燕云十六州','politics','point','year',NULL,NULL,'936年后晋建国及相关契丹册立、割地约定；具体交割过程跨越936年前后。',936,12,NULL,11243,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'石敬瑭借契丹援助赢得帝位，向辽割让燕云十六州，北方门户自此长期处于辽、金控制之下。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('later-zhou-recovers-ying-mo','后周北伐收复瀛、莫二州','battle','point','year',NULL,NULL,'显德六年（959），后周北伐并收复瀛、莫二州；相关州县归属及进军次序在史料中记载不一。',959,12,NULL,11519,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'后周世宗北伐，收复燕云南部的瀛州、莫州等地，但未能完成燕云十六州的整体收复。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('ming-moves-capital-to-beijing','永乐迁都北京','politics','point','year',NULL,NULL,'永乐十九年（1421年）正式迁都。',1421,12,NULL,17063,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'明成祖将都城由南京迁至北京，南京保留留都地位。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('qin-unifies-china','秦统一中国','politics','point','year',NULL,NULL,'秦王政二十六年，前221年；作为特别重大总纲事件保留，不等同于秦统一制度事件。',-221,12,NULL,-2629,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-221年，秦王政灭齐，完成对六国的兼并，结束战国列国分立。为使统治者名号与统一后的天下相称，秦廷议定新尊号，王政采用“皇帝”，自称始皇帝，意在使后世依次称二世、三世。秦由诸侯王号转为皇帝号，形成新的最高统治者称谓，并以郡县等制度治理统一后的疆域。',NULL,NULL,'[{"label":"《史记·秦始皇本纪》","url":"https://zh.wikisource.org/zh-hans/史記/卷006"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('qing-establishes-ili-general','清设伊犁将军','politics','point','year',NULL,NULL,'乾隆二十七年（1762年）；机构设置月份不详。',1762,12,NULL,21155,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'清廷在平定准噶尔后设置伊犁将军，建立对新疆军政事务的常设统辖机构。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('roc-moves-wartime-government-to-chongqing','国民政府迁都重庆','politics','point','month',NULL,NULL,'1937年11月国民政府决定迁渝；重庆市政协资料记载迁移过程。',1937,11,NULL,23254,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'抗日战争全面爆发后，国民政府迁往重庆，重庆成为战时陪都和全国抗战的重要政治中心。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('roc-returns-capital-to-nanjing','国民政府还都南京','politics','point','month',NULL,NULL,'1946年5月还都南京。',1946,5,NULL,23356,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'抗战胜利后，国民政府由重庆还都南京。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('shenlong-coup','神龙政变','politics','point','year',NULL,NULL,'长安五年正月癸卯，神龙政变发动；传统历日换算为公历705年2月20日。',705,12,NULL,8471,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'武则天病重之际，张柬之等朝臣联合禁军诛杀张易之、张昌宗，控制宫廷并促使太子李显监国。武则天随后退位，李显复位为唐中宗，武周结束、唐朝复辟；此后朝廷仍受韦后及其党羽影响。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('song-jin-maritime-alliance','宋金海上之盟','politics','point','year',NULL,NULL,'宣和二年（1120年）订盟；条约内容与实际执行过程跨越1120—1123年。',1120,12,NULL,13451,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'宋与金约定夹攻辽，宋希望借此取得燕云；辽亡后宋金关系迅速破裂，最终引向靖康之变。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('song-mongol-duanping-enter-luo','端平入洛','battle','point','year',NULL,NULL,'端平元年（1234）六月至八月，宋军曾入洛阳；相关月份为传统历月，具体公历日期未详。',1234,12,NULL,14819,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'南宋趁蒙古主力北撤，出兵收复开封、洛阳、商丘等北宋旧地。宋军一度进入洛阳，因补给困难且蒙古军反击而撤退；此役加剧了宋蒙对立。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('song-moves-capital-to-linan','南宋定都临安','politics','point','year',NULL,NULL,'绍兴八年（1138），宋廷正式定临安为行在；此前曾多次临幸临安。',1138,12,NULL,13667,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'宋高宗正式以临安为行在，临安由此成为南宋长期的政治中心。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('song-recovers-yanyun-six-prefectures','北宋短暂收复燕京及六州','politics','point','year',NULL,NULL,'宣和五年（1123年）；此处采用年精度，不把部分州县交割误写为十六州全部收复。',1123,12,NULL,13487,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'辽亡后金将燕京及附近六州交给北宋，宋短暂取得燕云南部，但实际控制很快因宋金冲突而动摇。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('sui-establishes-jinshi-examination','隋代设进士科','politics','point','year',NULL,NULL,'隋代进士科设置时间常系于大业元年（605），部分地方志系于大业二年（606）。',605,12,NULL,7271,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'隋炀帝设进士科，以考试选拔人才，成为科举制度形成的重要节点。此后考试取士逐步发展为历代官员选拔的重要途径。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('sui-moves-to-daxing','隋文帝迁都大兴','politics','point','year',NULL,NULL,'开皇三年（583），隋文帝由旧长安城迁入新建的大兴城。',583,12,NULL,7007,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'隋文帝迁入新建的大兴城，取代旧长安城成为隋朝都城。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('tang-forced-move-to-luoyang','昭宗东迁洛阳','politics','point','year',NULL,NULL,'天祐元年（904年）正月迁都；《旧唐书·昭宗本纪》记载此事。',904,12,NULL,10859,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'朱全忠迫使唐昭宗离开长安迁往洛阳，长安遭到毁坏，唐朝政治中心自此未能恢复。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('tang-restored-capital-to-changan','唐中宗还都长安','politics','point','year',NULL,NULL,'神龙二年（706年）还都长安；武周复唐发生于705年。',706,12,NULL,8483,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'神龙政变后唐朝复辟，中宗次年还都长安，结束武周时期以洛阳为政治中心的阶段。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('tang-tubo-changqing-alliance','唐蕃长庆会盟','politics','point','year',NULL,NULL,'长庆元年至二年（821—822），唐蕃分阶段会盟并立碑。',821,12,NULL,9863,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'唐与吐蕃订立长庆会盟，约定边界与和平关系，是唐蕃长期战争后重要的边疆秩序节点。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('tang-two-tax-law','两税法推行','politics','point','year',NULL,NULL,'建中元年（780年）颁行；《旧唐书·杨炎传》及《资治通鉴》记其制度与施行。',780,12,NULL,9371,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'唐德宗采纳杨炎建议，按居住地和资产等确定税额，分夏、秋两季征收，取代以丁身为主要依据的租庸调征收格局。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('tanglong-coup','唐隆政变','politics','point','year',NULL,NULL,'景龙四年六月二十日（唐隆元年，710年），唐隆政变发动；传统历日换算为公历7月21日。',710,12,NULL,8531,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'唐中宗死后，韦太后临朝并控制禁军。临淄王李隆基与太平公主联络禁军发动政变，诛杀韦太后及安乐公主等韦氏势力；少帝李重茂退位，李旦复位为唐睿宗，李隆基被立为皇太子。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('western-han-grace-order','推恩令颁行','politics','point','year',NULL,NULL,'元朔二年（前127年）；《汉书·主父偃传》载偃建议推恩，武帝从其计。',-127,12,NULL,-1501,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'汉武帝采纳主父偃建议，允许诸侯王将封地分给子弟为列侯，由朝廷另立侯国。诸侯王国因此逐代析分，中央对地方的控制加强。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('western-han-protectorate-of-western-regions','西域都护府建立','politics','point','year',NULL,NULL,'神爵二年，前60年；具体设置月份不详。',-60,12,NULL,-697,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'西汉在西域设置都护，标志中央政权对西域的经略由军事往来推进到持续行政管理。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('western-han-salt-iron-monopoly','盐铁官营','politics','point','year',NULL,NULL,'元狩四年（前119年）前后推行；盐铁专营的设置与各地落实并非单一日期。',-119,12,NULL,-1405,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'汉武帝将盐、铁经营纳入国家专营，由官府设官管理生产和销售，以增加财政收入、支持对匈奴战争。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('wu-zhou-moves-capital-to-luoyang','武周迁都洛阳','politics','point','year',NULL,NULL,'天授元年（690年）；采用武周建立并以洛阳为都的年份。',690,12,NULL,8291,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'武则天称帝建立武周，以洛阳为都并称神都，政治中心由长安转至洛阳。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('xinyou-coup','辛酉政变','politics','point','year',NULL,NULL,'咸丰十一年（1861），九月三十日慈禧等发动政变，十一月初一开始垂帘听政；两日均为传统历法日期。',1861,12,NULL,22343,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'咸丰帝在热河病逝前安排载淳继位，并命载垣、端华、肃顺等八大臣赞襄政务。慈禧与慈安两宫太后联合恭亲王奕訢，在咸丰梓宫回京期间解除八大臣权力，载垣、端华被逼自尽，肃顺被处斩；两宫随后垂帘听政，清廷权力格局由此改变。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('zhao-saqiu-coup','沙丘宫变','politics','point','year',NULL,NULL,'赵惠文王四年（前295年），据《史记·赵世家》；史书记沙丘之乱与围困经过，未载可确定的公历月日。沙丘宫具体地望有平乡、广宗等说。',-295,12,NULL,-3517,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'赵武灵王退位为主父后，仍试图调整赵国继承安排。前295年，他与赵惠文王赵何同游沙丘，公子章及田不礼借主父之名召赵何，起兵争位；赵成、李兑平乱后围困主父宫，赵武灵王被幽禁三月有余而饿死。事件加剧赵国统治集团内耗。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('zhou-jingwang-moves-to-chengzhou','周敬王迁都成周','politics','point','year',NULL,NULL,'前510年营建新城并迁居的通行系年；《左传》记王子朝之乱，迁居缘由见杜预注。',-510,12,NULL,-6097,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'王子朝之乱后，王城仍有其党羽活动。周敬王据杜预注的传统解释迁居王城以东的新成周，以避乱自安。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('zhou-nanwang-moves-to-western-zhou-capital','赧王徙居西周','politics','point','year',NULL,NULL,'仅知周赧王时期迁居西周国王城，具体年份有异说；都城资料将此事约系于前314年。',-314,12,NULL,-3745,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'周赧王被迫迁居西周国王城，当时此处仍是西周国都；这是寄居避难，不表述为正式迁都。',NULL,NULL,'[]');
